<?php get_header(); $query = igp_input( $_GET, 'query' ); $category = igp_input( $_GET, 'category' ); $sort = igp_input( $_GET, 'sort', 'featured' ); $page = max( 1, get_query_var( 'paged' ) ); $args = array( 'post_type' => 'igp_product', 'post_status' => 'publish', 'posts_per_page' => 24, 'paged' => $page, 's' => $query, 'igp_catalogue_search' => true ); if ( $category ) { $args['tax_query'] = array( array( 'taxonomy' => 'igp_category', 'field' => 'slug', 'terms' => $category ) ); } if ( 'name' === $sort ) { $args['orderby'] = 'title'; $args['order'] = 'ASC'; } elseif ( 'latest' === $sort ) { $args['orderby'] = 'date'; } else { $args['meta_query'] = array( 'relation'=>'OR', 'featured_rank'=>array( 'key'=>'_igp_featured', 'compare'=>'EXISTS' ), array( 'key'=>'_igp_featured', 'compare'=>'NOT EXISTS' ) ); $args['orderby'] = array( 'featured_rank'=>'DESC','title'=>'ASC' ); } if ( $manufacturer = igp_input( $_GET,'manufacturer' ) ) { $args['meta_query'] = array( $args['meta_query'] ?? array(), array( 'key'=>'_igp_manufacturer','value'=>$manufacturer ) ); } if ( $tag = igp_input( $_GET,'part_tag' ) ?: igp_input( $_GET,'tag' ) ) { $args['tax_query'][] = array( 'taxonomy'=>'igp_tag','field'=>'slug','terms'=>$tag ); } $products = new WP_Query( $args ); ?>
<div class="page shell"><nav class="breadcrumbs" aria-label="Breadcrumb"><a href="<?php echo esc_url( home_url( '/' ) ); ?>">Home</a><span>/</span><span>Products</span></nav><header class="page-heading"><p class="eyebrow">Complete catalogue</p><h1>Generator parts<br>for every major system.</h1><p>Search the current catalogue or narrow it by the system you are servicing.</p></header><form class="catalogue-controls" method="get" action="<?php echo esc_url( get_post_type_archive_link( 'igp_product' ) ); ?>"><label class="search-input"><span class="sr-only">Search products</span><input type="search" name="query" placeholder="Search parts, function or part number" value="<?php echo esc_attr( $query ); ?>"></label><details class="filter-sheet"><summary>Filters</summary><div class="filter-panel"><label>Category<select name="category"><option value="">All categories</option><?php foreach ( igp_categories() as $term ) : ?><option value="<?php echo esc_attr( $term->slug ); ?>" <?php selected( $category, $term->slug ); ?>><?php echo esc_html( $term->name ); ?></option><?php endforeach; ?></select></label><label>Manufacturer<input name="manufacturer" value="<?php echo esc_attr( $manufacturer ); ?>"></label><label>Part tag<select name="part_tag"><option value="">All tags</option><?php foreach ( get_terms( array( 'taxonomy'=>'igp_tag','hide_empty'=>true ) ) as $term ) : ?><option value="<?php echo esc_attr( $term->slug ); ?>" <?php selected( $tag,$term->slug ); ?>><?php echo esc_html( $term->name ); ?></option><?php endforeach; ?></select></label><button type="submit">Apply filters</button></div></details><label class="sort-select"><span class="sr-only">Sort products</span><select name="sort" data-auto-submit><option value="featured" <?php selected( $sort, 'featured' ); ?>>Featured first</option><option value="name" <?php selected( $sort, 'name' ); ?>>Name A–Z</option><option value="latest" <?php selected( $sort, 'latest' ); ?>>Latest</option></select></label><button type="submit" class="sr-only">Search</button></form><p class="results-count"><?php echo esc_html( $products->found_posts ); ?> components found</p><?php if ( $products->have_posts() ) : ?><div class="product-grid catalogue-grid"><?php while ( $products->have_posts() ) : $products->the_post(); get_template_part( 'template-parts/product', 'card' ); endwhile; ?></div><nav class="pagination" aria-label="Catalogue pagination"><?php echo wp_kses_post( paginate_links( array( 'total' => $products->max_num_pages, 'current' => $page, 'add_args' => array_filter( array( 'query' => $query, 'category' => $category, 'sort' => $sort ) ) ) ) ); ?></nav><?php wp_reset_postdata(); else : ?><div class="empty-state"><h2>No matching parts found.</h2><p>Try a broader term or clear the filters to view the complete catalogue.</p><a class="button button-dark" href="<?php echo esc_url( igp_url( 'products/' ) ); ?>">Clear filters</a></div><?php endif; ?></div><?php get_footer(); ?>
